relay.schema:
CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS pairing_codes (
  code TEXT PRIMARY KEY, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, used_at INTEGER
);
CREATE TABLE IF NOT EXISTS devices (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE,
  created_at INTEGER NOT NULL, revoked_at INTEGER, last_seen_at INTEGER
);
CREATE TABLE IF NOT EXISTS projects (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, icon TEXT NOT NULL DEFAULT '',
  instructions TEXT NOT NULL DEFAULT '', models TEXT NOT NULL DEFAULT '{}',
  state TEXT NOT NULL DEFAULT 'waking', created_at INTEGER NOT NULL, last_active_at INTEGER NOT NULL,
  spend_cap_daily REAL NOT NULL DEFAULT -1.0,
  project_token_hash TEXT
);
CREATE TABLE IF NOT EXISTS chats (
  id TEXT PRIMARY KEY, project_id TEXT NOT NULL, title TEXT NOT NULL DEFAULT 'New chat',
  is_pinned INTEGER NOT NULL DEFAULT 0, position INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL, doc_epoch INTEGER NOT NULL DEFAULT 1
);
CREATE INDEX IF NOT EXISTS chats_project ON chats(project_id, position);
CREATE TABLE IF NOT EXISTS sandboxes (
  project_id TEXT PRIMARY KEY, provider TEXT NOT NULL, sandbox_id TEXT,
  daytona_state TEXT, device_id TEXT NOT NULL, box_token_hash TEXT NOT NULL, mcp_token TEXT NOT NULL,
  snapshot TEXT, region TEXT, last_started_at INTEGER, last_stopped_at INTEGER, last_seen_at INTEGER,
  box_url TEXT, preview_token TEXT, local_pid INTEGER
);
-- One Daytona computer per user (design change 2026-10-15): every project of a user is a workspace
-- on that box. `sandboxes` above is the legacy per-project registry, kept for migration only.
CREATE TABLE IF NOT EXISTS boxes (
  user_id TEXT PRIMARY KEY, provider TEXT NOT NULL, sandbox_id TEXT,
  daytona_state TEXT, device_id TEXT NOT NULL, box_token_hash TEXT NOT NULL, mcp_token TEXT NOT NULL,
  snapshot TEXT, region TEXT, last_started_at INTEGER, last_stopped_at INTEGER, last_seen_at INTEGER,
  box_url TEXT, preview_token TEXT, local_pid INTEGER, migrated_from TEXT NOT NULL DEFAULT '[]'
);
-- A box create in flight (#2262): written before the provider is asked for the sandbox, removed
-- once the row holds the sandbox id or the create failed. A row left here after a restart names
-- the sandbox that may be running without a row pointing at it.
CREATE TABLE IF NOT EXISTS box_creates (
  user_id TEXT PRIMARY KEY, sandbox_name TEXT NOT NULL, provider TEXT NOT NULL, snapshot TEXT,
  replacing TEXT, started_at INTEGER NOT NULL
);
-- Per-user box class: the Daytona snapshot (which fixes vCPU/RAM/disk) a user's box is created
-- from; NULL = the relay default (ARBOS_DAYTONA_SNAPSHOT). Raise a user's class later by setting
-- it and recreating the box; no code change needed.
CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY, snapshot TEXT, spend_cap_usd REAL NOT NULL DEFAULT 25.0, created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS box_wake_jobs (
  user_id TEXT PRIMARY KEY, reason TEXT NOT NULL, due_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL, last_error TEXT
);
CREATE TABLE IF NOT EXISTS rows (
  room TEXT NOT NULL, seq INTEGER NOT NULL, device TEXT NOT NULL, batch_id TEXT NOT NULL,
  bytes BLOB NOT NULL, created_at INTEGER NOT NULL,
  PRIMARY KEY (room, seq)
);
CREATE UNIQUE INDEX IF NOT EXISTS rows_batch ON rows(room, batch_id);
-- Rows the relay could not decode as a Loro update, moved out of `rows` so that compaction can
-- proceed. The bytes are kept, never served: `rooms::quarantine_undecodable_rows` moves a row here
-- and the relay then checkpoints over its seq, which is the only way to reopen a room whose
-- compaction has wedged.
--
-- This table is deliberately OUTSIDE every read path over `rows`, and that is what it is FOR, not an
-- oversight to tidy up. In particular `rooms::checkpoint_covers_store` must never union it. The
-- wedge this table exists to fix is caused by a row that cannot be imported into any snapshot being
-- counted as missing from it, forever; a validation walk that reads quarantine re-imports exactly
-- those bytes, fails again, and restores the original bug in full. "While we are here, we should
-- validate against everything we have stored" is the one change that must not be made.
--
-- `batch_id` is carried, and uniquely indexed, for a reason that outlives this table's own purpose:
-- see `Db::row_seq_for_batch`.
CREATE TABLE IF NOT EXISTS quarantine (
  room TEXT NOT NULL, seq INTEGER NOT NULL, device TEXT NOT NULL, batch_id TEXT NOT NULL,
  bytes BLOB NOT NULL, created_at INTEGER NOT NULL, quarantined_at INTEGER NOT NULL,
  PRIMARY KEY (room, seq)
);
CREATE UNIQUE INDEX IF NOT EXISTS quarantine_batch ON quarantine(room, batch_id);
CREATE TABLE IF NOT EXISTS checkpoints (
  room TEXT PRIMARY KEY, seq INTEGER NOT NULL, frontier BLOB NOT NULL, bytes BLOB NOT NULL,
  size INTEGER NOT NULL, created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS room_seq (room TEXT PRIMARY KEY, head INTEGER NOT NULL, floor INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS blobs (
  project_id TEXT NOT NULL, key TEXT NOT NULL, size INTEGER NOT NULL, mime TEXT, created_at INTEGER NOT NULL,
  PRIMARY KEY (project_id, key)
);
CREATE TABLE IF NOT EXISTS usage (
  id INTEGER PRIMARY KEY AUTOINCREMENT, project_id TEXT NOT NULL, at INTEGER NOT NULL, api TEXT NOT NULL,
  model TEXT NOT NULL, input INTEGER NOT NULL, output INTEGER NOT NULL, cache_read INTEGER NOT NULL,
  cache_write INTEGER NOT NULL, usd REAL NOT NULL, latency_ms INTEGER NOT NULL, ttfb_ms INTEGER
);
CREATE INDEX IF NOT EXISTS usage_project_at ON usage(project_id, at);
CREATE TABLE IF NOT EXISTS wake_jobs (
  project_id TEXT PRIMARY KEY, reason TEXT NOT NULL, due_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL, last_error TEXT
);
CREATE TABLE IF NOT EXISTS push_queue (
  id INTEGER PRIMARY KEY AUTOINCREMENT, project_id TEXT NOT NULL, kind TEXT NOT NULL, payload TEXT NOT NULL,
  created_at INTEGER NOT NULL, delivered_at INTEGER
);
-- What each user's box reported in its last `/box/hello` (agentd commit, crate version, image).
CREATE TABLE IF NOT EXISTS box_agentd (
  user_id TEXT PRIMARY KEY, sha TEXT, version TEXT, image TEXT, reported_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS timings (
  id INTEGER PRIMARY KEY AUTOINCREMENT, project_id TEXT NOT NULL, kind TEXT NOT NULL, ms INTEGER NOT NULL,
  detail TEXT, at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS connectors (
  id TEXT PRIMARY KEY, provider TEXT NOT NULL, label TEXT NOT NULL DEFAULT '', scopes TEXT NOT NULL DEFAULT '[]',
  status TEXT NOT NULL DEFAULT 'needs_auth', config TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL,
  last_used_at INTEGER, last_error TEXT
);
CREATE TABLE IF NOT EXISTS connector_tokens (
  connector_id TEXT PRIMARY KEY, access_token TEXT NOT NULL, refresh_token TEXT, expires_at INTEGER,
  token_type TEXT NOT NULL DEFAULT 'Bearer', updated_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS oauth_states (
  state TEXT PRIMARY KEY, provider TEXT NOT NULL, code_verifier TEXT NOT NULL, redirect_uri TEXT NOT NULL,
  scopes TEXT NOT NULL DEFAULT '[]', created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS connector_outbox (
  id INTEGER PRIMARY KEY AUTOINCREMENT, provider TEXT NOT NULL, action TEXT NOT NULL, args TEXT NOT NULL,
  created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS routines (
  id TEXT PRIMARY KEY, project_id TEXT NOT NULL, chat_id TEXT NOT NULL, name TEXT NOT NULL,
  prompt TEXT NOT NULL, trigger TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1,
  created_at INTEGER NOT NULL, last_run_at INTEGER, next_run_at INTEGER
);
CREATE INDEX IF NOT EXISTS routines_due ON routines(enabled, next_run_at);
CREATE TABLE IF NOT EXISTS routine_runs (
  id TEXT PRIMARY KEY, routine_id TEXT NOT NULL, started_at INTEGER NOT NULL, finished_at INTEGER,
  status TEXT NOT NULL, message_id TEXT, note TEXT
);
CREATE INDEX IF NOT EXISTS routine_runs_routine ON routine_runs(routine_id, started_at);
CREATE TABLE IF NOT EXISTS skills (
  id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '',
  tags TEXT NOT NULL DEFAULT '[]', when_to_use TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '',
  origin_project_id TEXT, shared INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1,
  created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE VIRTUAL TABLE IF NOT EXISTS skills_fts USING fts5(text, id UNINDEXED, tokenize = 'porter unicode61');
CREATE TABLE IF NOT EXISTS channel_bindings (
  id TEXT PRIMARY KEY, platform TEXT NOT NULL, external_chat_id TEXT NOT NULL, external_user_id TEXT NOT NULL,
  project_id TEXT NOT NULL, chat_id TEXT NOT NULL, label TEXT NOT NULL DEFAULT '', bound_at INTEGER NOT NULL,
  UNIQUE(platform, external_chat_id, external_user_id)
);
CREATE TABLE IF NOT EXISTS channel_pair_codes (
  code TEXT PRIMARY KEY, project_id TEXT NOT NULL, chat_id TEXT NOT NULL, created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL, used_at INTEGER
);
CREATE TABLE IF NOT EXISTS channel_hints (
  platform TEXT NOT NULL, external_chat_id TEXT NOT NULL, external_user_id TEXT NOT NULL, hinted_at INTEGER NOT NULL,
  PRIMARY KEY (platform, external_chat_id, external_user_id)
);
CREATE TABLE IF NOT EXISTS channel_seen (event_key TEXT PRIMARY KEY, seen_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS channel_outbox (
  id INTEGER PRIMARY KEY AUTOINCREMENT, platform TEXT NOT NULL, external_chat_id TEXT NOT NULL, text TEXT NOT NULL,
  request_id TEXT NOT NULL, status TEXT NOT NULL, detail TEXT, binding_id TEXT, created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS audit (
  id INTEGER PRIMARY KEY AUTOINCREMENT, project_id TEXT NOT NULL, kind TEXT NOT NULL, entry TEXT NOT NULL,
  at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS audit_project ON audit(project_id, at);
CREATE TABLE IF NOT EXISTS local_devices (
  device_id TEXT PRIMARY KEY, name TEXT NOT NULL, hostname TEXT NOT NULL DEFAULT '', os TEXT NOT NULL DEFAULT '',
  home TEXT NOT NULL DEFAULT '', connected INTEGER NOT NULL DEFAULT 0, last_seen INTEGER, first_seen INTEGER NOT NULL,
  allow_reads INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS vault_items (
  id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, kind TEXT NOT NULL,
  fields TEXT NOT NULL, allowed_hosts TEXT NOT NULL DEFAULT '[]',
  created_at INTEGER NOT NULL, last_used_at INTEGER, daytona_secrets TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE IF NOT EXISTS vault_requests (
  id TEXT PRIMARY KEY, project_id TEXT NOT NULL, chat_id TEXT NOT NULL DEFAULT '',
  item_id TEXT, item_name TEXT NOT NULL, purpose TEXT NOT NULL DEFAULT '', use_kind TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL, decided_at INTEGER, expires_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS vault_requests_project ON vault_requests(project_id, created_at);
-- Fork lineage: dest project → source project, until the workspace copy finishes (or forever as a hint).
CREATE TABLE IF NOT EXISTS project_forks (
  project_id TEXT PRIMARY KEY, source_project_id TEXT NOT NULL, created_at INTEGER NOT NULL
);
-- Agent-hosted sites (arbos.life/<prefix>/<app>/, #2060). The prefix is fixed per user on the
-- first publish; sites carry the live manifest; versions keep every published manifest; pending
-- rows are begin→commit sessions; events are the audit trail; quotas override the defaults.
CREATE TABLE IF NOT EXISTS site_prefixes (
  user_id TEXT PRIMARY KEY, prefix TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS sites (
  user_id TEXT NOT NULL, app TEXT NOT NULL, prefix TEXT NOT NULL, status TEXT NOT NULL,
  version INTEGER NOT NULL, manifest TEXT NOT NULL, bytes INTEGER NOT NULL, files INTEGER NOT NULL,
  created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, published_at INTEGER,
  edge_synced_at INTEGER, takedown_reason TEXT, takedown_by TEXT,
  PRIMARY KEY (user_id, app)
);
CREATE TABLE IF NOT EXISTS site_versions (
  user_id TEXT NOT NULL, app TEXT NOT NULL, version INTEGER NOT NULL, manifest TEXT NOT NULL,
  bytes INTEGER NOT NULL, files INTEGER NOT NULL, created_at INTEGER NOT NULL,
  PRIMARY KEY (user_id, app, version)
);
CREATE TABLE IF NOT EXISTS site_pending (
  user_id TEXT NOT NULL, app TEXT NOT NULL, files TEXT NOT NULL, created_at INTEGER NOT NULL,
  PRIMARY KEY (user_id, app)
);
CREATE TABLE IF NOT EXISTS site_blobs (
  sha256 TEXT PRIMARY KEY, size INTEGER NOT NULL, created_at INTEGER NOT NULL, edge_pushed_at INTEGER
);
CREATE TABLE IF NOT EXISTS site_events (
  id INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER NOT NULL, user_id TEXT NOT NULL, app TEXT NOT NULL,
  kind TEXT NOT NULL, actor TEXT NOT NULL, version INTEGER, bytes INTEGER, files INTEGER, detail TEXT
);
CREATE INDEX IF NOT EXISTS site_events_at ON site_events(at);
CREATE TABLE IF NOT EXISTS site_quotas (
  user_id TEXT PRIMARY KEY, max_sites INTEGER, max_bytes INTEGER, publish_blocked INTEGER NOT NULL DEFAULT 0
);

relay.people_schema:
CREATE TABLE IF NOT EXISTS people_chats (
  id TEXT PRIMARY KEY, kind TEXT NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL,
  deleted_at INTEGER, title TEXT, image_key TEXT, avatar_leaf INTEGER, avatar_leaf_color INTEGER,
  description TEXT
);
CREATE TABLE IF NOT EXISTS people_members (
  chat_id TEXT NOT NULL, member TEXT NOT NULL, role TEXT NOT NULL, added_by TEXT NOT NULL,
  joined_at INTEGER NOT NULL, left_at INTEGER, settings TEXT NOT NULL DEFAULT '{}',
  muted INTEGER NOT NULL DEFAULT 0, silenced INTEGER NOT NULL DEFAULT 0,
  silenced_until INTEGER, banned_at INTEGER,
  PRIMARY KEY (chat_id, member)
);
CREATE INDEX IF NOT EXISTS people_members_member ON people_members(member);
CREATE TABLE IF NOT EXISTS gate_decisions (
  chat_id TEXT NOT NULL, message_id TEXT NOT NULL, agent_id TEXT NOT NULL, handle TEXT NOT NULL,
  decision TEXT NOT NULL, reason TEXT NOT NULL, chosen TEXT NOT NULL DEFAULT '[]',
  confidence REAL, addressee TEXT, model TEXT, latency_ms INTEGER, cost_usd REAL, at INTEGER NOT NULL,
  PRIMARY KEY (chat_id, message_id, agent_id)
);
CREATE INDEX IF NOT EXISTS gate_decisions_chat_at ON gate_decisions(chat_id, at);
CREATE TABLE IF NOT EXISTS people_reads (
  chat_id TEXT NOT NULL, device_id TEXT NOT NULL, seq INTEGER NOT NULL DEFAULT 0,
  at INTEGER NOT NULL, hidden INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (chat_id, device_id)
);
CREATE TABLE IF NOT EXISTS blocks (
  blocker TEXT NOT NULL, blocked TEXT NOT NULL, created_at INTEGER NOT NULL,
  PRIMARY KEY (blocker, blocked)
);
CREATE TABLE IF NOT EXISTS user_pushes (
  id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL, device_id TEXT NOT NULL,
  kind TEXT NOT NULL, payload TEXT NOT NULL, chat_id TEXT, created_at INTEGER NOT NULL, delivered_at INTEGER
);
CREATE INDEX IF NOT EXISTS user_pushes_device ON user_pushes(device_id, delivered_at);
CREATE TABLE IF NOT EXISTS project_members (
  project_id TEXT NOT NULL, user_id TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'member',
  added_by TEXT NOT NULL, joined_at INTEGER NOT NULL, left_at INTEGER,
  PRIMARY KEY (project_id, user_id)
);
CREATE INDEX IF NOT EXISTS project_members_user ON project_members(user_id);
CREATE TABLE IF NOT EXISTS invites (
  code TEXT PRIMARY KEY, github_login TEXT NOT NULL, inviter_user_id TEXT NOT NULL,
  target_kind TEXT NOT NULL, target_id TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL,
  accepted_at INTEGER, accepted_user_id TEXT, revoked_at INTEGER
);
CREATE INDEX IF NOT EXISTS invites_login ON invites(github_login);
CREATE TABLE IF NOT EXISTS people_chat_invites (
  id TEXT PRIMARY KEY, chat_id TEXT NOT NULL, code TEXT NOT NULL UNIQUE, created_by TEXT NOT NULL,
  created_at INTEGER NOT NULL, expires_at INTEGER, uses_left INTEGER, revoked_at INTEGER
);
CREATE INDEX IF NOT EXISTS people_chat_invites_chat ON people_chat_invites(chat_id, created_at);
CREATE TABLE IF NOT EXISTS rate_events (
  user_id TEXT NOT NULL, kind TEXT NOT NULL, at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS rate_events_user ON rate_events(user_id, kind, at);

push_schema:
CREATE TABLE IF NOT EXISTS push_tokens (
  device_id TEXT PRIMARY KEY, user_id TEXT NOT NULL, platform TEXT NOT NULL, token TEXT NOT NULL,
  environment TEXT NOT NULL, bundle_id TEXT NOT NULL, app_version TEXT NOT NULL DEFAULT '',
  updated_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS push_tokens_user ON push_tokens(user_id);
CREATE TABLE IF NOT EXISTS chat_events (
  id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id TEXT NOT NULL, project_id TEXT,
  message_id TEXT NOT NULL, sender_user TEXT, created_at INTEGER NOT NULL,
  UNIQUE (chat_id, message_id)
);
CREATE INDEX IF NOT EXISTS chat_events_chat ON chat_events(chat_id, id);
CREATE TABLE IF NOT EXISTS chat_user_reads (
  user_id TEXT NOT NULL, chat_id TEXT NOT NULL, event_id INTEGER NOT NULL, at INTEGER NOT NULL,
  PRIMARY KEY (user_id, chat_id)
);
CREATE TABLE IF NOT EXISTS chat_user_archive (
  user_id TEXT NOT NULL, chat_id TEXT NOT NULL, archived_at INTEGER NOT NULL,
  PRIMARY KEY (user_id, chat_id)
);
CREATE TABLE IF NOT EXISTS space_user_archive (
  user_id TEXT NOT NULL, space_id TEXT NOT NULL, kind TEXT NOT NULL, archived_at INTEGER NOT NULL,
  PRIMARY KEY (user_id, space_id)
);
CREATE TABLE IF NOT EXISTS chat_user_cursor (
  user_id TEXT NOT NULL, chat_id TEXT NOT NULL, seq INTEGER NOT NULL, at INTEGER NOT NULL,
  PRIMARY KEY (user_id, chat_id)
);
CREATE TABLE IF NOT EXISTS message_authors (
  chat_id TEXT NOT NULL, message_id TEXT NOT NULL, sender TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  PRIMARY KEY (chat_id, message_id)
);

box_schema:
CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);

-- Room cursor + snapshot committed together (crdt-sync §2.3).
CREATE TABLE IF NOT EXISTS room_docs (
  room TEXT PRIMARY KEY, cursor INTEGER NOT NULL DEFAULT 0, snapshot BLOB, acked_vv BLOB, updated_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS chats (
  id TEXT PRIMARY KEY, title TEXT NOT NULL DEFAULT 'New chat', is_pinned INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL, last_message_at INTEGER,
  compaction_summary TEXT, compacted_through TEXT, compaction_version INTEGER NOT NULL DEFAULT 0,
  pi_session_path TEXT
);

CREATE TABLE IF NOT EXISTS sessions (
  id TEXT PRIMARY KEY, subagent_id TEXT, path TEXT, cwd TEXT, model TEXT, thinking_level TEXT,
  last_cursor TEXT, compactions INTEGER NOT NULL DEFAULT 0, context_pct INTEGER NOT NULL DEFAULT 0,
  harness TEXT NOT NULL, role TEXT NOT NULL, harness_version TEXT, created_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS subagents (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, purpose TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '',
  tags TEXT NOT NULL DEFAULT '[]', last_seen_at INTEGER, status TEXT NOT NULL DEFAULT 'idle',
  turns INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, last_turn_at INTEGER, retired_reason TEXT,
  harness TEXT NOT NULL, handles TEXT NOT NULL DEFAULT '[]', chat_id TEXT
);

-- T3: one row per message / tool call / tool output / compaction / memory event.
CREATE TABLE IF NOT EXISTS t3 (
  id TEXT PRIMARY KEY, thread_id TEXT NOT NULL, subagent_id TEXT, session_id TEXT, kind TEXT NOT NULL,
  role TEXT, at INTEGER NOT NULL, text TEXT NOT NULL, source TEXT, size INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS t3_thread_at ON t3(thread_id, at);
CREATE INDEX IF NOT EXISTS t3_at ON t3(at);
CREATE VIRTUAL TABLE IF NOT EXISTS t3_fts USING fts5(text, id UNINDEXED, thread_id UNINDEXED, kind UNINDEXED, tokenize = 'porter unicode61');

CREATE TABLE IF NOT EXISTS memory (
  id TEXT PRIMARY KEY, tier TEXT NOT NULL, thread_id TEXT, kind TEXT NOT NULL, scope TEXT NOT NULL,
  text TEXT NOT NULL, source TEXT, valid_at INTEGER, invalid_at INTEGER, created_at INTEGER NOT NULL, expired_at INTEGER,
  supersedes TEXT NOT NULL DEFAULT '[]', confidence REAL NOT NULL DEFAULT 0.5, importance INTEGER NOT NULL DEFAULT 5,
  last_accessed_at INTEGER, access_count INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS memory_tier_live ON memory(tier, expired_at);
CREATE VIRTUAL TABLE IF NOT EXISTS memory_fts USING fts5(text, id UNINDEXED, tier UNINDEXED, tokenize = 'porter unicode61');

CREATE TABLE IF NOT EXISTS memory_decision_log (
  id TEXT PRIMARY KEY, side TEXT NOT NULL, event_id TEXT, gate TEXT, action TEXT, target_ids TEXT,
  reason TEXT, confidence REAL, model TEXT, latency_ms INTEGER, usage TEXT, created_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS handles (
  id TEXT PRIMARY KEY, chat_id TEXT, session_id TEXT, kind TEXT NOT NULL, chars INTEGER NOT NULL, lines INTEGER NOT NULL,
  path TEXT NOT NULL, note TEXT NOT NULL, blob_key TEXT, created_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS scratch (
  chat_id TEXT NOT NULL, name TEXT NOT NULL, value TEXT NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (chat_id, name)
);

CREATE TABLE IF NOT EXISTS turn_metrics (
  id TEXT PRIMARY KEY, chat_id TEXT NOT NULL, message_id TEXT NOT NULL, route TEXT, ttft_ms INTEGER, route_ms INTEGER,
  total_ms INTEGER, tool_calls INTEGER NOT NULL DEFAULT 0, escalated INTEGER NOT NULL DEFAULT 0, usage TEXT, created_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS asks (
  id TEXT PRIMARY KEY, chat_id TEXT, session_id TEXT, question TEXT NOT NULL, answered INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL
);

-- Approval cards (feature approve): the doc part is the source of truth for clients; this row
-- survives a restart so a late decision still dispatches.
CREATE TABLE IF NOT EXISTS approvals (
  id TEXT PRIMARY KEY, chat_id TEXT NOT NULL, message_id TEXT NOT NULL, title TEXT NOT NULL, risk TEXT NOT NULL,
  payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL,
  decided_at INTEGER, decided_by TEXT, reason TEXT
);

-- Approved drafts with no connector to deliver them (feature approve, until connectors land).
CREATE TABLE IF NOT EXISTS outbox (
  id TEXT PRIMARY KEY, approval_id TEXT NOT NULL, channel TEXT NOT NULL, recipient TEXT NOT NULL, subject TEXT,
  body TEXT NOT NULL, created_at INTEGER NOT NULL
);

-- Background jobs the main agent starts with `start_job` (duplex design §2.3): one row per job, from
-- the ask to its delivery. `subagent_id` names the harness session that runs it.
CREATE TABLE IF NOT EXISTS jobs (
  id TEXT PRIMARY KEY, chat_id TEXT NOT NULL, ask_message_id TEXT NOT NULL, subagent_id TEXT,
  title TEXT NOT NULL, kind TEXT NOT NULL, brief TEXT NOT NULL, touches TEXT NOT NULL DEFAULT '[]',
  state TEXT NOT NULL, last_step TEXT NOT NULL DEFAULT '', last_step_at INTEGER,
  created_at INTEGER NOT NULL, started_at INTEGER, ended_at INTEGER, error TEXT,
  delivered_key TEXT, restarts INTEGER NOT NULL DEFAULT 0, steers TEXT NOT NULL DEFAULT '[]'
);
CREATE INDEX IF NOT EXISTS jobs_subagent_created ON jobs(subagent_id, created_at DESC);

-- Every worker a job has ever been given, not only the one it is on now (bug AO). `jobs.subagent_id`
-- is overwritten by each fresh worker, and the processes the replaced worker left behind are
-- reachable only under *its* id — so a cancel that reads the column alone asks the kernel about the
-- wrong session. This is the job's whole history of workers, which is what a cancel sweeps.
CREATE TABLE IF NOT EXISTS job_workers (
  job_id TEXT NOT NULL, subagent_id TEXT NOT NULL, at INTEGER NOT NULL,
  PRIMARY KEY (job_id, subagent_id)
);
CREATE INDEX IF NOT EXISTS job_workers_job ON job_workers(job_id, at);
